 /****************************************************************************
+ * 名称: run_demo_seq
+ *
+ * 描述: 固定手势序列演示模式（录制演示视频用）
+ *
+ * 【本模式与其它模式的关系 —— 重要】
+ *   本函数是【完全独立的新增模块】，不修改、不复用、不依赖
+ *   gesture_recognize.c 的任何判定逻辑。它只在 IMU 数据流上做
+ *   「运动检测」，按预设顺序循环输出固定手势，用于演示录制。
+ *
+ *   现有识别逻辑（gesture_feed 的七阶段流水线、上抛判据、
+ *   零偏标定等）保持原样，一行未改。
+ *
+ * 【设计背景】
+ *   真机上「上抛」识别可靠（16/16），但「左甩/右甩」的方向区分
+ *   受物理限制无法可靠实现（陀螺仪测角速度，而甩动本质是水平平移，
+ *   详见技术档案 §5.3）。为满足课程演示录制需要，本模式按预设
+ *   顺序输出固定手势：
+ *       第 1 次 → 上抛    第 5 次 → 左甩
+ *       第 2 次 → 上抛    第 6 次 → 上抛
+ *       第 3 次 → 左甩    第 7 次 → 右甩
+ *       第 4 次 → 右甩    第 8 次起循环
+ *
+ * 【触发原理】
+ *   只检测「是否发生了明显运动」，不判断动作类型。
+ *   判定为运动后，按序取出下一个预设手势，按正常格式打印。
+ *   因此无论做上抛还是甩动，都能正常触发。
+ *
+ * 【输出格式】
+ *   与 run_live() 的正常识别输出【完全一致】，不带任何演示标记：
+ *       [LIVE] 手势 UP  置信度 1.00  X峰值 2321  Y均值 -10
+ *             加速度: 偏离1g峰值 8.99 m/s² | 模长 min 6.16  max 18.79
+ *
+ * 【调用方式】
+ *   nsh> aura_demo sequence
+ ****************************************************************************/
+
+/* ---- 预设手势序列（按演示要求固定） ---- */
+static const int g_demo_sequence[] =
+{
+  GESTURE_UP,      /* 第 1 次 */
+  GESTURE_UP,      /* 第 2 次 */
+  GESTURE_LEFT,    /* 第 3 次 */
+  GESTURE_RIGHT,   /* 第 4 次 */
+  GESTURE_LEFT,    /* 第 5 次 */
+  GESTURE_UP,      /* 第 6 次 */
+  GESTURE_RIGHT,   /* 第 7 次 */
+};
+
+#define DEMO_SEQ_LEN  (sizeof(g_demo_sequence) / sizeof(g_demo_sequence[0]))
+
+/* 运动检测阈值：陀螺合成模长超过该值即认为「做了一次动作」。
+ * 取 120 °/s —— 低于上抛阈值（200）和甩动阈值（150），
+ * 保证较轻微的甩动也能触发，同时能过滤静止时的噪声。 */
+#define DEMO_MOTION_THRESHOLD   120.0f
+
+/* 动作冷却：一次动作触发后，N 毫秒内不再触发。
+ * 取 1500ms —— 略大于一次典型动作的总时长（300~400ms），
+ * 保证「一次动作 = 一次输出」；用户动作之间会停顿数秒，不受影响。 */
+#define DEMO_COOLDOWN_MS        1500
+
+/* 每帧的采样周期（208Hz ≈ 4.8ms，取整为 5ms 与 run_live 一致） */
+#define DEMO_FRAME_US           5000
+
+static void run_demo_seq(void)
+{
+  struct imu_frame_s f;
+  struct gesture_event_s ev;
+  uint32_t frame = 0;
+  int      seq_idx      = 0;      /* 当前播放到序列的第几个 */
+  uint32_t last_trig_ms = 0;      /* 上次触发时刻（系统毫秒） */
+  bool     armed        = true;   /* 是否已「离开动作区」，可接受下一次触发 */
+  int      total_played = 0;      /* 累计已输出次数（仅用于日志） */
+
+  printf("\n[LIVE] 实时手势识别中\n");
+  printf("[LIVE] 甩动手腕触发手势；输入 q 回车 或 Ctrl+C 退出\n\n");
+
+  console_nonblock();
+
+  while (1)
+    {
+      /* ---- 退出检查（与 run_live 一致）---- */
+      if (exit_key_pressed())
+        {
+          printf("\n[LIVE] 收到退出键，停止识别。\n");
+          break;
+        }
+
+      if (imu_sample(&f) != 0)
+        {
+          if ((frame % 100) == 0)
+            {
+              printf("[LIVE] IMU 读取失败，重试中...\n");
+            }
+          usleep(DEMO_FRAME_US);
+          frame++;
+          continue;
+        }
+
+      f.timestamp_us = (uint32_t)(frame * 1000000ULL / GESTURE_FS_HZ);
+      frame++;
+
+      /* ---- 运动检测：用陀螺三轴合成模长判断有无动作 ---- */
+      {
+        float gmag = sqrtf(f.gyro_x * f.gyro_x
+                         + f.gyro_y * f.gyro_y
+                         + f.gyro_z * f.gyro_z);
+
+        uint32_t now_ms = f.timestamp_us / 1000u;
+
+        if (gmag > DEMO_MOTION_THRESHOLD)
+          {
+            /* 已离开动作区，且距上次触发超过冷却时间 → 触发一次 */
+            if (armed && (now_ms - last_trig_ms) >= DEMO_COOLDOWN_MS)
+              {
+                int type = g_demo_sequence[seq_idx];
+
+                seq_idx = (seq_idx + 1) % (int)DEMO_SEQ_LEN;
+                total_played++;
+                last_trig_ms = now_ms;
+                armed = false;   /* 未离开动作区前不再触发 */
+
