════ imu_sample 实现 ════
 * 输入: frame —— 输出参数
 *
 * 返回: 0 成功；负值为 errno
 ****************************************************************************/
int imu_source_read(struct imu_frame_s *frame)
{
  struct lsm6dsl_sensor_data_s d;
  int ret;

  if (frame == NULL)
    {
      return -EINVAL;
    }

  if (g_state != 1)
    {
      return -EPERM;
    }

  memset(&d, 0, sizeof(d));

  ret = ioctl(g_sensor_fd, SNIOC_LSM6DSLSENSORREAD, (unsigned long)&d);
  if (ret < 0)
    {
      return -errno;
    }

  /* ---------- 陀螺仪：原始值 → °/s (±2000dps, 70 mdps/LSB) ---------- */
  frame->gyro_x = (float)d.g_x_data * 70.0f / 1000.0f;
  frame->gyro_y = (float)d.g_y_data * 70.0f / 1000.0f;
  frame->gyro_z = (float)d.g_z_data * 70.0f / 1000.0f;

  /* ---------- 加速度：原始值 → m/s² (±2g, 0.061 mg/LSB) ---------- */
  frame->accel_x = (float)d.x_data * 0.061f / 1000.0f * 9.80665f;
  frame->accel_y = (float)d.y_data * 0.061f / 1000.0f * 9.80665f;
  frame->accel_z = (float)d.z_data * 0.061f / 1000.0f * 9.80665f;

  /* ---------- 温度 ---------- */
  frame->temp_c = (float)d.temperature / 256.0f + 25.0f;

  /* ---------- 时间戳（毫秒，由驱动提供） ---------- */
  frame->timestamp_us = (uint32_t)d.timestamp * 1000u;

  return 0;
}

/****************************************************************************
 * 名称: imu_source_deinit
 ****************************************************************************/
int imu_source_deinit(void)
{
  if (g_sensor_fd >= 0)
    {
      ioctl(g_sensor_fd, SNIOC_STOP, 0);
      close(g_sensor_fd);
      g_sensor_fd = -1;
    }
  g_state = 0;
  return 0;
}

/****************************************************************************
 * 名称: imu_source_state
 ****************************************************************************/
int imu_source_state(void)
{
  return g_state;
