+/* ==========================================================================
+ * 屏显模块（像素风）—— 用于 sequence 演示模式
+ * ==========================================================================
+ * 【设计说明】
+ *   本模块完全独立实现，不依赖 LVGL、不依赖任何图形库，直接操作
+ *   framebuffer 显存（/dev/fb0，RGB565 / 390x450 / bpp=16）。
+ *
+ *   风格为「像素风」：所有图形由大色块矩形拼成，无抗锯齿、无渐变。
+ *   字体为自绘的 8x8 点阵字模（仅含演示所需的字母）。
+ *
+ *   【为什么不用 LVGL】
+ *     本演示只需显示三个单词，引入 LVGL 会显著增加复杂度和编译依赖；
+ *     直接写显存更轻量，也不会与现有 LVGL 代码产生耦合。
+ *
+ *   【性能考虑】
+ *     全屏填充 390x450 约 17.5 万像素，纯整数运算，耗时可控。
+ *     仅在「动作发生」时刷新画面，静止时不重绘，避免持续占用 CPU
+ *     影响 IMU 采样与动作检测灵敏度。
+ * ========================================================================== */
+
+#ifdef CONFIG_VIDEO_FB
+
+/* ---- RGB565 颜色（与 run_lcd_diag 同一格式） ---- */
+#define PX_BLACK     0x0000u
+#define PX_WHITE     0xFFFFu
+#define PX_DARKBG    0x0841u   /* 深蓝黑背景 #080C10 近似 */
+#define PX_PANEL     0x18E3u   /* 面板底色 */
+#define PX_CYAN      0x07FFu   /* 青色（UP 用） */
+#define PX_GREEN     0x07E0u   /* 绿色（LEFT 用） */
+#define PX_ORANGE    0xFD20u   /* 橙色（RIGHT 用） */
+#define PX_GRAY      0x8410u   /* 灰色（等待态） */
+#define PX_DIM       0x4208u   /* 暗灰 */
+
+/* ---- 屏幕参数 ---- */
+#define DEMO_SCR_W   390
+#define DEMO_SCR_H   450
+#define DEMO_SCR_STRIDE  780   /* 390 * 2 字节 */
+
+/* ---- framebuffer 状态（模块内静态，避免占用调用方栈） ---- */
+static volatile uint16_t *g_fb    = NULL;
+static uint32_t           g_fb_len = 0;   /* 像素总数 */
+
+/****************************************************************************
+ * 名称: pgfx_init
+ * 描述: 打开 /dev/fb0 并取得显存指针。成功返回 true。
+ ****************************************************************************/
+static bool pgfx_init(void)
+{
+  int fd;
+  struct fb_planeinfo_s pinfo;
+
+  if (g_fb != NULL)
+    {
+      return true;   /* 已初始化 */
+    }
+
+  fd = open("/dev/fb0", O_RDWR);
+  if (fd < 0)
+    {
+      printf("[GFX] 打开 /dev/fb0 失败 (errno=%d)，屏显不可用\n", errno);
+      return false;
+    }
+
+  memset(&pinfo, 0, sizeof(pinfo));
+  if (ioctl(fd, FBIOGET_PLANEINFO, (unsigned long)&pinfo) != 0 ||
+      pinfo.fbmem == NULL || pinfo.fblen == 0)
+    {
+      printf("[GFX] 读取 framebuffer 信息失败，屏显不可用\n");
+      close(fd);
+      return false;
+    }
+
+  if (pinfo.bpp != 16)
+    {
+      printf("[GFX] 像素位深 %d bpp（本模块仅支持 16bpp RGB565），屏显不可用\n",
+             pinfo.bpp);
+      close(fd);
+      return false;
+    }
+
+  g_fb     = (volatile uint16_t *)pinfo.fbmem;
+  g_fb_len = pinfo.fblen / 2;
+
+  printf("[GFX] 屏显就绪: %d x %d, %d bpp\n",
+         DEMO_SCR_W, DEMO_SCR_H, pinfo.bpp);
+  return true;
+}
+
+/****************************************************************************
+ * 名称: pgfx_pixel
+ * 描述: 画一个像素（带边界检查）
+ ****************************************************************************/
+static void pgfx_pixel(int x, int y, uint16_t c)
+{
+  if (x < 0 || y < 0 || x >= DEMO_SCR_W || y >= DEMO_SCR_H)
+    {
+      return;
+    }
+  g_fb[y * (DEMO_SCR_STRIDE / 2) + x] = c;
+}
+
+/****************************************************************************
+ * 名称: pgfx_fill
+ * 描述: 填充矩形（像素风基本单位）
+ ****************************************************************************/
+static void pgfx_fill(int x, int y, int w, int h, uint16_t c)
+{
+  int i, j;
+
+  for (j = 0; j < h; j++)
+    {
+      for (i = 0; i < w; i++)
+        {
+          pgfx_pixel(x + i, y + j, c);
+        }
+    }
+}
+
+/****************************************************************************
+ * 名称: pgfx_clear
+ * 描述: 清屏
+ ****************************************************************************/
+static void pgfx_clear(uint16_t c)
+{
+  uint32_t i;
+
+  for (i = 0; i < g_fb_len; i++)
+    {
+      g_fb[i] = c;
+    }
+}
+
+/****************************************************************************
+ * 名称: pgfx_fill_rect_border
+ * 描述: 画空心矩形边框
+ ****************************************************************************/
+static void pgfx_fill_rect_border(int x, int y, int w, int h, int t, uint16_t c)
+{
+  pgfx_fill(x, y, w, t, c);                 /* 上 */
+  pgfx_fill(x, y + h - t, w, t, c);         /* 下 */
+  pgfx_fill(x, y, t, h, c);                 /* 左 */
+  pgfx_fill(x + w - t, y, t, h, c);         /* 右 */
+}
+
+/* ==========================================================================
+ * 8x8 点阵字模（像素风字体）
+ * ==========================================================================
+ * 每个字符 8 字节，每字节一行，bit7 在左、bit0 在右。
+ * 仅包含演示所需字符：U P L E F T R I G H 与空格。
+ * ========================================================================== */
+typedef struct
+{
+  char ch;
+  uint8_t rows[8];
+} pgfx_glyph_t;
+
+static const pgfx_glyph_t g_glyphs[] =
+{
+  { 'U', { 0x66,0x66,0x66,0x66,0x66,0x66,0x66,0x3C } },
+  { 'P', { 0x7C,0x66,0x66,0x7C,0x60,0x60,0x60,0x60 } },
+  { 'L', { 0x60,0x60,0x60,0x60,0x60,0x60,0x60,0x7E } },
+  { 'E', { 0x7E,0x60,0x60,0x7C,0x60,0x60,0x60,0x7E } },
+  { 'F', { 0x7E,0x60,0x60,0x7C,0x60,0x60,0x60,0x60 } },
+  { 'T', { 0x7E,0x18,0x18,0x18,0x18,0x18,0x18,0x18 } },
+  { 'R', { 0x7C,0x66,0x66,0x7C,0x6C,0x66,0x66,0x66 } },
+  { 'I', { 0x7E,0x18,0x18,0x18,0x18,0x18,0x18,0x7E } },
+  { 'G', { 0x3C,0x66,0x60,0x6E,0x66,0x66,0x66,0x3C } },
+  { 'H', { 0x66,0x66,0x66,0x7E,0x66,0x66,0x66,0x66 } },
+  { 'W', { 0x63,0x63,0x63,0x6B,0x7F,0x77,0x63,0x63 } },
+  { 'A', { 0x18,0x3C,0x66,0x66,0x7E,0x66,0x66,0x66 } },
+  { 'D', { 0x78,0x6C,0x66,0x66,0x66,0x66,0x6C,0x78 } },
+  { 'N', { 0x66,0x76,0x7E,0x7E,0x6E,0x66,0x66,0x66 } },
+  { 'S', { 0x3C,0x66,0x60,0x3C,0x06,0x66,0x66,0x3C } },
+  { 'O', { 0x3C,0x66,0x66,0x66,0x66,0x66,0x66,0x3C } },
+  { ' ', { 0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00 } },
+};
+
+#define GLYPH_COUNT  (sizeof(g_glyphs) / sizeof(g_glyphs[0]))
+
+/****************************************************************************
+ * 名称: pgfx_glyph
+ * 描述: 查字模。找不到返回 NULL。
+ ****************************************************************************/
+static const uint8_t *pgfx_glyph(char c)
+{
+  size_t i;
+
+  if (c >= 'a' && c <= 'z')
+    {
+      c = (char)(c - 'a' + 'A');
+    }
+
+  for (i = 0; i < GLYPH_COUNT; i++)
+    {
+      if (g_glyphs[i].ch == c)
+        {
+          return g_glyphs[i].rows;
+        }
+    }
+
+  return NULL;
+}
+
+/****************************************************************************
+ * 名称: pgfx_text
+ * 描述: 用点阵字模绘制字符串（像素风，无缩放）
+ * 输入: x, y  —— 左上角坐标
+ *       h     —— 字符高度（8 的整数倍，用于放大）
+ ****************************************************************************/
+static void pgfx_text(int x, int y, const char *s, int h, uint16_t c)
+{
+  int scale = h / 8;
+  int cx    = x;
+
+  if (scale < 1)
+    {
+      scale = 1;
+    }
+
+  while (*s)
+    {
+      const uint8_t *rows = pgfx_glyph(*s);
+
+      if (rows != NULL)
+        {
+          int r, b;
+
+          for (r = 0; r < 8; r++)
+            {
+              for (b = 0; b < 8; b++)
+                {
+                  if (rows[r] & (0x80 >> b))
+                    {
+                      pgfx_fill(cx + b * scale, y + r * scale,
+                                scale, scale, c);
+                    }
+                }
+            }
+        }
+
+      cx += 8 * scale + scale;   /* 字符间距 = 1 个 scale */
+      s++;
+    }
+}
+
+/****************************************************************************
+ * 名称: pgfx_arrow
+ * 描述: 绘制像素风箭头
+ * 输入: dir —— 0=上 1=左 2=右
+ *       cx, cy —— 箭头中心
+ *       size —— 箭头半宽（像素）
+ ****************************************************************************/
+static void pgfx_arrow(int dir, int cx, int cy, int size, uint16_t c)
+{
+  int i;
+
+  if (dir == 0)
+    {
+      /* 向上箭头：倒三角 + 竖条 */
+      for (i = 0; i < size; i++)
+        {
+          pgfx_fill(cx - i, cy - size + i, i * 2 + 1, 1, c);
+        }
+      pgfx_fill(cx - size / 4, cy, size / 2 + 1, size, c);
+    }
+  else if (dir == 1)
+    {
+      /* 向左箭头：三角 + 横条 */
+      for (i = 0; i < size; i++)
+        {
+          pgfx_fill(cx - size + i, cy - i, 1, i * 2 + 1, c);
+        }
+      pgfx_fill(cx, cy - size / 4, size, size / 2 + 1, c);
+    }
+  else
+    {
+      /* 向右箭头 */
+      for (i = 0; i < size; i++)
+        {
+          pgfx_fill(cx + size - i, cy - i, 1, i * 2 + 1, c);
+        }
+      pgfx_fill(cx - size, cy - size / 4, size, size / 2 + 1, c);
+    }
+}
+
+/****************************************************************************
