+ * 描述: 显示「等待动作」待机画面
+ ****************************************************************************/
+static void pgfx_show_wait(void)
+{
+  int cy = DEMO_SCR_H / 2;
+
+  pgfx_clear(PX_DARKBG);
+
+  /* 外框 */
+  pgfx_fill_rect_border(10, 10, DEMO_SCR_W - 20, DEMO_SCR_H - 20,
+                        3, PX_DIM);
+
+  /* 顶部标题条 */
+  pgfx_fill(10, 10, DEMO_SCR_W - 20, 4, PX_GRAY);
+
+  /* 中央提示 */
+  pgfx_text(DEMO_SCR_W / 2 - 4 * 12, cy - 40, "READY", 24, PX_GRAY);
+
+  /* 装饰性静止方块 */
+  pgfx_fill(DEMO_SCR_W / 2 - 20, cy + 10, 40, 40, PX_DIM);
+
+  /* 底部说明 */
+  pgfx_text(DEMO_SCR_W / 2 - 6 * 6, cy + 90, "MOVE  HAND", 12, PX_DIM);
+}
+
+/****************************************************************************
+ * 名称: pgfx_show_gesture
+ * 描述: 显示识别到的手势（像素风画面）
+ * 输入: type —— GESTURE_UP / GESTURE_LEFT / GESTURE_RIGHT
+ ****************************************************************************/
+static void pgfx_show_gesture(int type)
+{
+  const char *label;
+  int         dir;
+  uint16_t    col;
+  int         cx = DEMO_SCR_W / 2;
+  int         cy = DEMO_SCR_H / 2;
+  int         tw;
+
+  if (type == GESTURE_UP)
+    {
+      label = "UP";
+      dir   = 0;
+      col   = PX_CYAN;
+    }
+  else if (type == GESTURE_LEFT)
+    {
+      label = "LEFT";
+      dir   = 1;
+      col   = PX_GREEN;
+    }
+  else
+    {
+      label = "RIGHT";
+      dir   = 2;
+      col   = PX_ORANGE;
+    }
+
+  pgfx_clear(PX_DARKBG);
+
+  /* 外框（用该手势的颜色，形成强提示） */
+  pgfx_fill_rect_border(10, 10, DEMO_SCR_W - 20, DEMO_SCR_H - 20,
+                        6, col);
+
+  /* 顶部色条 */
+  pgfx_fill(10, 10, DEMO_SCR_W - 20, 14, col);
+
+  /* 中央大箭头 */
+  pgfx_arrow(dir, cx, cy - 60, 46, col);
+
+  /* 手势名称（大字） */
+  tw = 0;
+  {
+    const char *s = label;
+    while (*s)
+      {
+        tw += 9;
+        s++;
+      }
+  }
+  pgfx_text(cx - (tw * 4) / 2, cy + 40, label, 32, col);
+
+  /* 底部装饰：三段进度条（纯装饰，增加"仪器感"） */
+  pgfx_fill(60, DEMO_SCR_H - 70, 80, 8, PX_DIM);
+  pgfx_fill(155, DEMO_SCR_H - 70, 80, 8, col);
+  pgfx_fill(250, DEMO_SCR_H - 70, 80, 8, PX_DIM);
+}
+
+#else  /* !CONFIG_VIDEO_FB */
+
+/* 未启用 framebuffer 时，所有屏显函数退化为空操作，不影响串口演示 */
+static bool pgfx_init(void)               { return false; }
+static void pgfx_show_wait(void)          { }
+static void pgfx_show_gesture(int type)   { (void)type; }
+
+#endif /* CONFIG_VIDEO_FB */
+
